[
  {
    "text": "The minimum depth of focus required for single-exposure full-field DRAM storage node contacts without stitching at 28 nm pitch is 85 nm, which exceeds the claimed >80 nm depth of focus by at least 5 nm.",
    "topic": "Depth of focus threshold missed"
  },
  {
    "text": "No published experimental data demonstrates central obscuration achieving process window requirements across the entire full-field area without stitching at 28 nm pitch.",
    "topic": "Lack of full-field experimental evidence"
  },
  {
    "text": "The claimed process window of >80 nm DoF and >15% EL has not been simultaneously validated with full-field overlay, OPC fidelity, and defect density measurements.",
    "topic": "Incomplete validation scope"
  },
  {
    "text": "Simulated process window improvements with central obscuration for sub-30 nm pitch contacts do not yet translate to confirmed stitching-free full-field manufacturability.",
    "topic": "Simulation-to-experiment gap"
  }
]
